// Potansiyometre ile servo kontrolü
#include <Servo.h>

const int POT = A0;
const int SERVO_PIN = 9;

Servo servo;

void setup() {
  servo.attach(SERVO_PIN);
}

void loop() {
  int deger = analogRead(POT);            // 0 ... 1023
  int aci = map(deger, 0, 1023, 0, 180);  // 0 ... 180 derece
  servo.write(aci);
  delay(15);                              // servonun hedefe gitmesi için süre
}
